package br.casasala.painel;
import java.io.*;import java.net.*;import java.security.*;import java.util.*;import org.json.*;
/** Samsung 2016+ LAN remote. Acknowledges transport, never invents TV state. */
public final class SamsungRemote{
 private final String ip,mac;private String token;private final int port;private volatile Socket socket;private InputStream in;private OutputStream out;private final SecureRandom random=new SecureRandom();
 public SamsungRemote(String address,String hardware,int remotePort,String savedToken)throws Exception{if(!address.matches("[0-9]{1,3}(\\.[0-9]{1,3}){3}"))throw new Exception("Informe o IP da TV.");String[] p=address.split("\\.");for(int i=0;i<4;i++)if(Integer.parseInt(p[i])>255)throw new Exception("IP da TV inválido.");if(remotePort!=8001&&remotePort!=8002)throw new Exception("Porta da TV: 8001 ou 8002.");ip=address;mac=hardware==null?"":hardware;port=remotePort;token=savedToken==null?"":savedToken;}
 public synchronized String token(){return token;}
 public synchronized void pair()throws Exception{try{ensureConnected();}catch(Exception e){close();throw e;}}
 public int volume()throws Exception{return rendering("GetVolume","","CurrentVolume");}
 public boolean muted()throws Exception{return rendering("GetMute","","CurrentMute")==1;}
 public int volume(int level)throws Exception{if(level<0||level>100)throw new Exception("Volume entre 0 e 100.");rendering("SetVolume","<DesiredVolume>"+level+"</DesiredVolume>","");return volume();}
 public boolean mute(boolean value)throws Exception{rendering("SetMute","<DesiredMute>"+(value?1:0)+"</DesiredMute>","");return muted();}
 private int rendering(String action,String arguments,String field)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://"+ip+":9197/upnp/control/RenderingControl1").openConnection();c.setConnectTimeout(1800);c.setReadTimeout(2200);c.setRequestMethod("POST");c.setRequestProperty("SOAPACTION","\"urn:schemas-upnp-org:service:RenderingControl:1#"+action+"\"");c.setRequestProperty("Content-Type","text/xml; charset=utf-8");byte[] body=("<?xml version=\"1.0\"?><s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"><s:Body><u:"+action+" xmlns:u=\"urn:schemas-upnp-org:service:RenderingControl:1\"><InstanceID>0</InstanceID><Channel>Master</Channel>"+arguments+"</u:"+action+"></s:Body></s:Envelope>").getBytes("UTF-8");try{c.setDoOutput(true);c.setFixedLengthStreamingMode(body.length);OutputStream output=c.getOutputStream();output.write(body);output.close();if(c.getResponseCode()!=200)throw new Exception("A TV não aceitou o ajuste de áudio por rede.");String xml=new String(readLimited(c.getInputStream(),65536),"UTF-8");if(field.length()==0)return 0;java.util.regex.Matcher match=java.util.regex.Pattern.compile("<"+field+">([0-9]{1,3})</"+field+">").matcher(xml);if(!match.find())throw new Exception("A TV não informou o estado do áudio.");int value=Integer.parseInt(match.group(1));if(value>100)throw new Exception("Estado de áudio inválido.");return value;}finally{c.disconnect();}}
 public JSONObject status()throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://"+ip+":8001/api/v2/").openConnection();c.setConnectTimeout(2200);c.setReadTimeout(2200);try{if(c.getResponseCode()!=200)throw new Exception("A TV não respondeu à identificação Samsung.");JSONObject info=new JSONObject(new String(readLimited(c.getInputStream(),65536),"UTF-8")),device=info.optJSONObject("device");if(device==null)throw new Exception("O endereço não identificou uma TV Samsung.");return new JSONObject().put("online",true).put("name",device.optString("name","TV Samsung")).put("model",device.optString("modelName")).put("mac",device.optString("wifiMac")).put("power",device.optString("PowerState","desconhecido")).put("token_supported",device.optString("TokenAuthSupport"));}finally{c.disconnect();}}
 public synchronized void key(String key,int repeats)throws Exception{if(!key.matches("KEY_[A-Z0-9_]{1,30}"))throw new Exception("Tecla da TV inválida.");if(repeats<1||repeats>10)throw new Exception("Quantidade de teclas inválida.");try{ensureConnected();for(int i=0;i<repeats;i++){JSONObject msg=new JSONObject().put("method","ms.remote.control").put("params",new JSONObject().put("Cmd","Click").put("DataOfCmd",key).put("Option","false").put("TypeOfRemote","SendRemoteKey"));frame(1,msg.toString().getBytes("UTF-8"));if(i+1<repeats)Thread.sleep(180);}}catch(Exception e){close();throw e;}}
 public synchronized void channel(int number)throws Exception{if(number<1||number>9999)throw new Exception("Canal inválido.");String digits=String.valueOf(number);for(int i=0;i<digits.length();i++)key("KEY_"+digits.charAt(i),1);key("KEY_ENTER",1);}
 public void wake()throws Exception{byte[] data=magicPacket(mac);DatagramSocket udp=new DatagramSocket();try{udp.setBroadcast(true);String subnet=ip.substring(0,ip.lastIndexOf('.')+1)+"255";udp.send(new DatagramPacket(data,data.length,InetAddress.getByName(subnet),9));udp.send(new DatagramPacket(data,data.length,InetAddress.getByName("255.255.255.255"),9));}finally{udp.close();}}
 public static byte[] magicPacket(String mac)throws Exception{String clean=mac==null?"":mac.replace(":","").replace("-","");if(!clean.matches("[A-Fa-f0-9]{12}"))throw new Exception("Cadastre o MAC da TV para tentar ligar por Wake-on-LAN.");byte[] packet=new byte[102];Arrays.fill(packet,0,6,(byte)255);for(int i=0;i<16;i++)for(int k=0;k<6;k++)packet[6+i*6+k]=(byte)Integer.parseInt(clean.substring(k*2,k*2+2),16);return packet;}
 private void ensureConnected()throws Exception{if(socket!=null&&!socket.isClosed())return;socket=new Socket();socket.connect(new InetSocketAddress(ip,port),4000);socket.setSoTimeout(12000);
  if(port==8002){javax.net.ssl.SSLSocket ssl=(javax.net.ssl.SSLSocket)((javax.net.ssl.SSLSocketFactory)javax.net.ssl.SSLSocketFactory.getDefault()).createSocket(socket,ip,port,true);ssl.startHandshake();if(!javax.net.ssl.HttpsURLConnection.getDefaultHostnameVerifier().verify(ip,ssl.getSession())){ssl.close();throw new Exception("O certificado da TV não pôde ser validado neste Android. Use o controle LAN compatível ou a ponte.");}socket=ssl;}
  in=socket.getInputStream();out=socket.getOutputStream();byte[] nonce=new byte[16];random.nextBytes(nonce);String challenge=b64(nonce);String path="/api/v2/channels/samsung.remote.control?name="+URLEncoder.encode(b64("Painel Galaxy Tab".getBytes("UTF-8")),"UTF-8")+(token.length()>0?"&token="+URLEncoder.encode(token,"UTF-8"):"");out.write(("GET "+path+" HTTP/1.1\r\nHost: "+ip+":"+port+"\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: "+challenge+"\r\nSec-WebSocket-Version: 13\r\n\r\n").getBytes("UTF-8"));out.flush();String header=header(in);if(!header.startsWith("HTTP/1.1 101")&&!header.startsWith("HTTP/1.0 101"))throw new Exception("A TV recusou o controle remoto nesta porta.");String expected=b64(MessageDigest.getInstance("SHA-1").digest((challenge+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").getBytes("UTF-8")));boolean accepted=false;for(String line:header.split("\r\n"))if(line.toLowerCase(Locale.US).startsWith("sec-websocket-accept:")&&expected.equals(line.substring(line.indexOf(':')+1).trim()))accepted=true;if(!accepted)throw new Exception("Resposta WebSocket da TV inválida.");
  for(int i=0;i<12;i++){JSONObject event=new JSONObject(new String(readFrame(),"UTF-8"));String name=event.optString("event");if(name.equals("ms.channel.connect")){JSONObject data=event.optJSONObject("data");if(data!=null&&data.optString("token").length()>0)token=data.optString("token");return;}if(name.indexOf("unauthorized")>=0||name.indexOf("timeOut")>=0)throw new Exception("Autorize o Painel na tela da TV e tente novamente.");}throw new Exception("Aguardando autorização do controle na TV.");
 }
 private void frame(int opcode,byte[] data)throws Exception{if(data.length>65535)throw new Exception("Mensagem da TV muito grande.");out.write(128|opcode);out.write(128|(data.length<126?data.length:126));if(data.length>=126){out.write(data.length>>8);out.write(data.length&255);}byte[] mask=new byte[4];random.nextBytes(mask);out.write(mask);for(int i=0;i<data.length;i++)out.write(data[i]^mask[i%4]);out.flush();}
 private byte[] readFrame()throws Exception{ByteArrayOutputStream data=new ByteArrayOutputStream();while(true){int first=readByte(in),second=readByte(in),code=first&15;long length=second&127;if(length==126)length=(readByte(in)<<8)|readByte(in);else if(length==127){length=0;for(int k=0;k<8;k++)length=(length<<8)|readByte(in);}if(length<0||length>131072||data.size()+length>131072)throw new Exception("Quadro da TV muito grande.");byte[] mask=(second&128)!=0?readExactly(in,4):null,body=readExactly(in,(int)length);if(mask!=null)for(int i=0;i<body.length;i++)body[i]^=mask[i%4];if(code==8)throw new Exception("A TV encerrou o controle remoto. Reconecte.");if(code==9){frame(10,body);continue;}if(code==10)continue;if(code!=1&&code!=0)continue;data.write(body);if((first&128)!=0)return data.toByteArray();}}
 private static int readByte(InputStream in)throws Exception{int b=in.read();if(b<0)throw new EOFException();return b;}private static byte[] readExactly(InputStream in,int n)throws Exception{byte[] b=new byte[n];int at=0;while(at<n){int count=in.read(b,at,n-at);if(count<0)throw new EOFException();at+=count;}return b;}
 private static String header(InputStream in)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();int end=0;while(b.size()<16384){int c=readByte(in);b.write(c);end=((end<<8)|c);if(end==0x0d0a0d0a)return new String(b.toByteArray(),"UTF-8");}throw new Exception("Cabeçalho da TV muito grande.");}
 private static byte[] readLimited(InputStream in,int limit)throws Exception{try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[2048];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>limit)throw new Exception("Resposta da TV muito grande.");out.write(buffer,0,n);}return out.toByteArray();}finally{in.close();}}
 public void close(){if(socket!=null)try{socket.close();}catch(Exception ignored){}socket=null;in=null;out=null;}
 private static final char[] BASE="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".toCharArray();private static String b64(byte[] b){StringBuilder out=new StringBuilder();for(int i=0;i<b.length;i+=3){int n=(b[i]&255)<<16;if(i+1<b.length)n|=(b[i+1]&255)<<8;if(i+2<b.length)n|=b[i+2]&255;out.append(BASE[n>>>18]).append(BASE[(n>>>12)&63]).append(i+1<b.length?BASE[(n>>>6)&63]:'=').append(i+2<b.length?BASE[n&63]:'=');}return out.toString();}
}
